function validate([edges, nums]) {
  const n = nums.length;
  if (n < 2 || n > 50000) return 'nums needs 2 to 50000 values.';
  if (edges.length !== n - 1) return 'edges needs exactly n - 1 entries.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 50000)) return 'Each value in nums is between 0 and 50000.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [u, v, length].';
    const [u, v, w] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge ends must be nodes 0 to n - 1.';
    if (!Number.isInteger(w) || w < 1 || w > 1000) return 'Edge lengths are between 1 and 1000.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree: no cycles or repeated edges.';
    root[a] = b;
  }
  return null;
}

