function longestSpecialPath(edges, nums) {
  const n = nums.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    graph[u].push([v, w]);
    graph[v].push([u, w]);
  }
  // Root the tree at 0 with a BFS, remembering each node's parent and the length of the edge up to it.
  const up = new Array(n).fill(-1), upLength = new Array(n).fill(0), seen = new Array(n).fill(false);
  const queue = [0];
  seen[0] = true;
  for (let i = 0; i < queue.length; i++)
    for (const [next, w] of graph[queue[i]])
      if (!seen[next]) { seen[next] = true; up[next] = queue[i]; upLength[next] = w; queue.push(next); }
  // From every node, climb toward the root while the values stay distinct; each step is a special path.
  let best = [0, 1];
  for (let end = 0; end < n; end++) {
    const values = new Set([nums[end]]);
    let length = 0, count = 1;
    for (let node = end; up[node] !== -1 && !values.has(nums[up[node]]); node = up[node]) {
      length += upLength[node];
      count++;
      values.add(nums[up[node]]);
      if (length > best[0] || (length === best[0] && count < best[1])) best = [length, count];
    }
  }
  return best;
}

