function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(502) : 2 + pick(9);
  const shape = ['random', 'random', 'path', 'star', 'deep'][pick(5)];
  // Shuffle the labels; half the time node 0 stays at the top of the shape, otherwise it may sit in the middle.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
  if (rand() < 0.5) { const z = order.indexOf(0); [order[0], order[z]] = [order[z], order[0]]; }
  // Small weights make equal lengths common, which exercises the fewest-nodes tie-break.
  const maxWeight = [3, 1000][pick(2)];
  const edges = [];
  for (let i = 1; i < n; i++) {
    const p = shape === 'path' ? i - 1 : shape === 'star' ? 0 : shape === 'deep' ? Math.max(0, i - 1 - pick(3)) : pick(i);
    const w = 1 + pick(maxWeight);
    edges.push(rand() < 0.5 ? [order[p], order[i], w] : [order[i], order[p], w]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const distinct = size === 'large' ? [2, 20, 500, 50001][pick(4)] : [1, 2, 3, 10][pick(4)];
  return [edges, Array.from({ length: n }, () => pick(distinct))];
}
